@props([ 'variant' => 'primary', 'size' => 'md', 'type' => 'button', 'href' => null, 'icon' => null, 'iconRight' => null, 'pill' => false, 'block' => false, 'loading' => false, 'disabled' => false, ]) @php $classes = [ 'ui-btn', 'ui-btn-' . $variant, 'ui-btn-' . $size, $pill ? 'ui-btn-pill' : '', $block ? 'ui-btn-block' : '', $loading ? 'is-loading' : '', $disabled ? 'is-disabled' : '', ]; $classes = trim(implode(' ', array_filter($classes))); @endphp @if($href) <a href="{{ $href }}" {{ $attributes->merge(['class' => $classes]) }} @if($disabled) tabindex="-1" aria-disabled="true" @endif> @if($icon) <i class="{{ $icon }}"></i> @endif {{ $slot }} @if($iconRight) <i class="{{ $iconRight }}"></i> @endif </a> @else <button type="{{ $type }}" {{ $attributes->merge(['class' => $classes]) }} @if($disabled || $loading) disabled @endif> @if($icon) <i class="{{ $icon }}"></i> @endif {{ $slot }} @if($iconRight) <i class="{{ $iconRight }}"></i> @endif </button> @endif